<template><div class="donut-layout"><div class="donut" :style="{background:gradient}"><div><strong>{{total}}</strong><span>全部上游</span></div></div><div class="donut-legend"><div v-for="(item,index) in data" :key="item.label"><i :style="{background:colors[index%colors.length]}"/><span>{{labels[item.label]||item.label}}</span><strong>{{item.value}}</strong></div><div v-if="!data.length" class="empty">暂无数据</div></div></div></template>
<script setup>import{computed}from"vue";const props=defineProps({data:{type:Array,default:()=>[]}}),colors=["#19c37d","#3b82f6","#f59e0b","#ef4444","#8b5cf6"],labels={healthy:"运行正常",synced:"已同步",changed:"发现变化",write_failed:"写入失败",failed:"检查失败",newapi_probe:"New API",direct:"Sub2API"},total=computed(()=>props.data.reduce((sum,item)=>sum+Number(item.value||0),0)),gradient=computed(()=>{if(!total.value)return"var(--fm-line-soft)";let cursor=0;return`conic-gradient(${props.data.map((item,index)=>{const start=cursor;cursor+=Number(item.value)/total.value*100;return`${colors[index%colors.length]} ${start}% ${cursor}%`}).join(",")})`});</script>
<style scoped>.donut-layout{display:grid;grid-template-columns:150px minmax(0,1fr);align-items:center;gap:24px}.donut{display:grid;place-items:center;width:146px;height:146px;border-radius:50%}.donut>div{display:grid;place-items:center;width:96px;height:96px;border-radius:50%;background:var(--fm-bg-card)}.donut strong{font-size:25px}.donut span{color:var(--fm-ink-muted);font-size:10px}.donut-legend{display:grid;gap:9px}.donut-legend>div{display:grid;grid-template-columns:9px 1fr auto;align-items:center;gap:8px;font-size:12px}.donut-legend i{width:8px;height:8px;border-radius:50%}.donut-legend strong{font-variant-numeric:tabular-nums}.donut-legend .empty{display:block;color:var(--fm-ink-muted)}@media(max-width:520px){.donut-layout{grid-template-columns:1fr}.donut{margin:auto}}</style>
